import { test, expect } from "@playwright/test"

// A4: the RGAA accessibility statement follows the official template and states
// the tests actually run. It is generated by the site, so it exists on every database.

const STATEMENTS = [
  {
    locale: "fr",
    title: "Déclaration d'accessibilité",
    sections: [
      "État de conformité",
      "Résultats des tests",
      "Contenus non accessibles",
      "Établissement de cette déclaration",
      "Retour d'information et contact",
      "Voies de recours",
    ],
    status: /non conforme/,
    date: "11 novembre 2026",
    contact: "formulaire de contact",
    ombudsman: /Défenseur des droits/,
  },
  {
    locale: "en",
    title: "Accessibility statement",
    sections: [
      "Compliance status",
      "Test results",
      "Non-accessible content",
      "Preparation of this statement",
      "Feedback and contact",
      "Enforcement procedure",
    ],
    status: /non-compliant/,
    date: "11 November 2026",
    contact: "contact form",
    ombudsman: /Défenseur des droits/,
  },
]

test.describe("accessibility statement", () => {
  for (const statement of STATEMENTS) {
    test(`${statement.locale}: follows the RGAA template`, async ({ page }) => {
      const response = await page.goto(`/${statement.locale}/accessibilite`)
      expect(response?.status()).toBe(200)
      await expect(page).toHaveTitle(new RegExp(statement.title))
      await expect(page.getByRole("heading", { level: 1 })).toHaveText(statement.title)

      const main = page.getByRole("main")
      await expect(main.getByRole("heading", { level: 2 })).toHaveText(statement.sections)
      await expect(main).toContainText(statement.status)
      await expect(main).toContainText(statement.date)
      await expect(main).toContainText("RGAA")

      await expect(main.getByRole("link", { name: statement.contact })).toHaveAttribute(
        "href",
        `/${statement.locale}/contact`
      )
      await expect(main.getByRole("link", { name: statement.ombudsman }).first()).toHaveAttribute(
        "href",
        /defenseurdesdroits\.fr/
      )
    })
  }

  test("is reached from the footer of every page", async ({ page }) => {
    await page.goto("/fr/evenements")
    await page.locator("footer").getByRole("link", { name: "Accessibilité" }).click()
    await expect(page).toHaveURL(/\/fr\/accessibilite$/)
    await expect(page.getByRole("heading", { level: 1 })).toHaveText("Déclaration d'accessibilité")
  })
})
